baselineGaps.query:
select jsonb_build_object(
'document_snapshot_rpc',to_regprocedure('public.freeze_estimate_v2_document_snapshot(uuid,uuid,timestamptz,bigint,text,text,jsonb,jsonb,jsonb)') is not null,
'generated_atomic_rpc',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='commit_generated_ouvrages' and p.pronargs=12),
'finalize_assembly_rpc',exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='finalize_estimate_assembly_calculation' and p.pronargs=8),
'reference_function_md5',(select md5(replace(p.prosrc,E'\r','')) from pg_proc p where oid='public.product_reference_price_proposal(uuid,numeric,text)'::regprocedure)
) as baseline_gaps;
